INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (1, 1, 2, 21, 'be_jun_sql_join', 'Выборка с соединением и агрегацией', 'code', 3, 20, 10.00, 'Сгенерируй задачу на SQL-выборку с одним JOIN и агрегацией. Предметная область — случайная из списка: доставка, библиотека, автосервис, стриминг. Схема из 2-3 таблиц приводится в условии. Ответ — один запрос.', 'Корректность результата — 6 баллов; отсутствие лишних подзапросов — 2; читаемость — 2.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (2, 1, 3, 34, 'be_mid_api_design', 'Проектирование REST-ресурса', 'open', 5, 25, 10.00, 'Опиши продуктовое требование и попроси спроектировать REST-ресурс: пути, методы, коды ответов, идемпотентность, пагинация. Домен выбирай случайно, объём требования — 5-7 предложений.', 'Корректные коды ответов — 3; идемпотентность изменяющих операций — 3; пагинация и фильтрация — 2; версионирование и обработка ошибок — 2.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (3, 1, 3, 35, 'be_mid_schema_fix', 'Поиск дефектов в схеме БД', 'open', 6, 30, 12.00, 'Приведи DDL на 3-4 таблицы с 3-4 намеренными дефектами (отсутствие FK, денормализация без причины, тип данных не по смыслу, пропущенный уникальный индекс). Попроси найти дефекты и предложить исправление.', 'По 3 балла за каждый найденный дефект с корректным обоснованием; максимум 12.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (4, 1, 4, 35, 'be_sen_concurrency', 'Конкурентный доступ и блокировки', 'case', 8, 35, 15.00, 'Опиши сценарий гонки при одновременном изменении общего ресурса (остатки на складе, бронирование мест). Попроси выбрать уровень изоляции и стратегию блокировки с обоснованием.', 'Диагноз гонки — 5; корректный уровень изоляции с обоснованием — 5; работоспособность решения под нагрузкой — 5.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (5, 2, 2, 15, 'fe_jun_state', 'Состояние компонента', 'code', 3, 20, 10.00, 'Сгенерируй задачу на управление локальным состоянием в React: форма с валидацией одного поля и блокировкой кнопки. Требование формулируй как пользовательский сценарий.', 'Работающая валидация — 5; отсутствие лишних ре-рендеров — 3; доступность — 2.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (6, 2, 3, 6, 'fe_mid_types', 'Типизация внешнего контракта', 'code', 5, 25, 10.00, 'Дай JSON-ответ внешнего API со вложенностью и необязательными полями. Попроси описать типы и безопасный разбор без any.', 'Отсутствие any — 4; корректная необязательность полей — 3; обработка несоответствия — 3.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (7, 5, 3, 38, 'ml_mid_rag', 'Выбор стратегии RAG', 'case', 6, 30, 12.00, 'Опиши корпус документов (объём, язык, структуру) и требование к качеству ответов. Попроси выбрать стратегию разбиения, модель эмбеддингов и способ оценки качества.', 'Обоснование чанкинга — 4; выбор модели под язык корпуса — 4; измеримые метрики — 4.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (8, 7, 3, 26, 'do_mid_k8s_debug', 'Диагностика падающего пода', 'case', 6, 25, 12.00, 'Приведи вывод kubectl describe/logs с одной из причин отказа (OOMKilled, CrashLoopBackOff из-за конфига, неготовый readiness). Попроси поставить диагноз и предложить исправление.', 'Верный диагноз — 6; исправление причины, а не симптома — 4; профилактика повторения — 2.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (9, 8, 2, 37, 'qa_jun_testdesign', 'Тест-дизайн по требованию', 'open', 3, 20, 10.00, 'Дай короткое требование к форме или API-методу. Попроси составить набор проверок: классы эквивалентности, граничные значения, негативные сценарии.', 'Классы эквивалентности — 4; границы — 3; негативные сценарии — 3.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
INSERT INTO assess.task_templates ("id", "specialization_id", "grade_id", "skill_id", "code", "title", "format", "difficulty", "expected_minutes", "max_score", "generator_prompt", "grading_rubric", "params_schema", "source", "version", "is_active", "usage_count", "avg_score", "created_at") OVERRIDING SYSTEM VALUE VALUES (10, 11, 7, 48, 'mkt_jun_content', 'Контент-план на неделю', 'open', 3, 20, 10.00, 'Опиши продукт и аудиторию. Попроси составить контент-план на неделю с форматами и целевыми метриками.', 'Соответствие аудитории — 4; разнообразие форматов — 3; измеримые метрики — 3.', NULL, 'manual', 1, TRUE, 0, NULL, '2026-10-06T15:16:02.600964+00:00');
