INSERT INTO assess.task_answers ("id", "session_id", "task_id", "answer_text", "answer_payload", "score", "max_score", "checked_by", "feedback", "submitted_at", "checked_at", "time_spent_sec", "paste_count", "focus_lost_count") OVERRIDING SYSTEM VALUE VALUES (1, '55555555-0000-4000-8000-000000000001'::uuid, '44444444-0000-4000-8000-000000000001'::uuid, 'POST /orders, PATCH /orders/{id}/items, POST /orders/{id}/cancel. Повтор защищён ключом Idempotency-Key, история — курсорная пагинация.', NULL, 8.50, 10.00, 'llm', 'Идемпотентность и пагинация раскрыты, не хватает версионирования API.', '2026-08-08T15:46:11.255692+00:00', '2026-08-08T16:26:11.255692+00:00', 1620, 0, 1);
