INSERT INTO match.chat_messages ("id", "thread_id", "run_id", "role", "content", "tool_payload", "tokens", "created_at") OVERRIDING SYSTEM VALUE VALUES (1, 'cccccccc-0000-4000-8000-000000000001'::uuid, 'bbbbbbbb-0000-4000-8000-000000000001'::uuid, 'assistant', 'Подобрала 10 кандидатов в категории backend.middle. Первый — с подтверждённым навыком проектирования БД и призовым местом ФСП.', NULL, 64, '2026-09-29T15:16:11.255692+00:00');
