INSERT INTO match.chat_messages ("id", "thread_id", "run_id", "role", "content", "tool_payload", "tokens", "created_at") OVERRIDING SYSTEM VALUE VALUES (3, 'cccccccc-0000-4000-8000-000000000001'::uuid, 'bbbbbbbb-0000-4000-8000-000000000002'::uuid, 'assistant', 'Уточнила: осталось 4 кандидата. Предыдущая подборка сохранена, к ней можно вернуться.', NULL, 42, '2026-09-29T15:22:11.255692+00:00');
INSERT INTO match.search_results ("run_id", "candidate_id", "stage", "rank", "vector_score", "llm_score", "final_score", "explanation", "is_shown", "created_at") VALUES ('bbbbbbbb-0000-4000-8000-000000000001'::uuid, '11111111-0000-4000-8000-000000000001'::uuid, 'llm', 1, 0.84210, 0.93000, 0.90000, 'Подтверждённый backend.middle, навык проектирования БД подтверждён тестом (10 из 12), призовое место на всероссийских соревнованиях ФСП. Вилка кандидата пересекается с вилкой потребности.', TRUE, '2026-10-06T15:16:11.295231+00:00');
INSERT INTO match.search_results ("run_id", "candidate_id", "stage", "rank", "vector_score", "llm_score", "final_score", "explanation", "is_shown", "created_at") VALUES ('bbbbbbbb-0000-4000-8000-000000000001'::uuid, '11111111-0000-4000-8000-000000000005'::uuid, 'llm', 2, 0.71050, 0.62000, 0.65000, 'Сильный инфраструктурный профиль, но специализация devops, а не backend: подходит как смежный вариант, если расширить потребность.', TRUE, '2026-10-06T15:16:11.295231+00:00');
